    static const char *data[] = { "__ZTVN10__cxxabiv117__class_type_infoE", "__ZTVN10__cxxabiv120__si_class_type_infoE",
                                  "__ZTVN10__cxxabiv121__vmi_class_type_infoE", NULL };
